-- Real PG component, all fixtures and any pg_net outbox inserts stay uncommitted.
-- All production triggers remain enabled. No model or external tool is invoked.
BEGIN;
CREATE TEMP TABLE mission_worker_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.mission_assert(name text,value boolean) RETURNS void LANGUAGE plpgsql AS $$
BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'mission work-product assertion failed: %',name; END IF; INSERT INTO mission_worker_checks VALUES(name); END $$;
CREATE FUNCTION pg_temp.mission_reject(name text,statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE rejected boolean:=false;
BEGIN
 BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF position(expected IN SQLERRM)=0 THEN RAISE EXCEPTION 'unexpected rejection for %: %',name,SQLERRM; END IF; rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'missing expected rejection: %',name; END IF;
 INSERT INTO mission_worker_checks VALUES(name);
END $$;
CREATE TEMP TABLE mission_worker_fixtures(name text PRIMARY KEY,customer_id uuid,mission_id uuid,run_id uuid,plan_id uuid,step_id uuid,audit_id uuid);
CREATE FUNCTION pg_temp.mission_fixture(label text,mode text DEFAULT 'ready') RETURNS void LANGUAGE plpgsql AS $$
DECLARE customer uuid:=gen_random_uuid(); mission uuid:=gen_random_uuid(); run uuid:=gen_random_uuid(); fixture_plan uuid; step uuid:=gen_random_uuid();
BEGIN
 INSERT INTO public.email_customers(id,display_name,google_drive_folder_status) VALUES(customer,'Mission worker rollback fixture','excluded');
 INSERT INTO public.sandy_tasks(id,customer_id,title,details,status,source_kind,metadata) VALUES(mission,customer,'Rollback internal mission','Only component state testing; no model or provider execution.','waiting','integration_test',jsonb_build_object('sandy_mission',true,'execution_state','awaiting_client_plan_review','plan_summary','Reversible draft pending client review'));
 SELECT id INTO fixture_plan FROM public.sandy_mission_runs WHERE mission_task_id=mission AND customer_id=customer AND stage='plan';
 IF fixture_plan IS NULL THEN RAISE EXCEPTION 'original mission enqueue trigger did not create real plan fixture'; END IF;
 UPDATE public.sandy_mission_runs SET state='completed' WHERE id=fixture_plan;
 INSERT INTO public.sandy_mission_runs(id,mission_task_id,customer_id,stage,state,run_key) VALUES(run,mission,customer,'execute','queued','rollback-executor:'||run);
 IF mode='ready' THEN
  INSERT INTO public.sandy_tasks(customer_id,parent_task_id,title,status,source_kind,metadata) VALUES(customer,mission,'Completed real same-plan prerequisite','completed','integration_test',jsonb_build_object('mission_run_id',fixture_plan,'plan_index',1,'stage','planned','assigned_to','sandy','approval_required',false));
 END IF;
 INSERT INTO public.sandy_tasks(id,customer_id,parent_task_id,title,details,status,source_kind,metadata)
 VALUES(step,customer,mission,'Prepare internal draft','Only provided project facts; mark unknown information.','todo','integration_test',jsonb_build_object('mission_run_id',fixture_plan,'plan_index',2,'stage','planned','assigned_to',CASE WHEN mode='no_eligible' THEN 'client' ELSE 'sandy' END,'approval_required',mode='no_eligible','depends_on',CASE WHEN mode='blocked' THEN '[99]'::jsonb ELSE '[1]'::jsonb END));
 INSERT INTO mission_worker_fixtures VALUES(label,customer,mission,run,fixture_plan,step,NULL);
END $$;
SELECT pg_temp.mission_fixture('success');
SELECT pg_temp.mission_fixture('unknown');
SELECT pg_temp.mission_fixture('changed');
SELECT pg_temp.mission_fixture('cancelled');
SELECT pg_temp.mission_fixture('foreign_plan');
SELECT pg_temp.mission_fixture('no_eligible','no_eligible');
SELECT pg_temp.mission_fixture('blocked','blocked');
SELECT pg_temp.mission_assert('closed mutation cost sensitive contract',is_mutation AND NOT api_exposed AND NOT ui_exposed AND NOT ai_exposed AND NOT verified AND
 (error_contract->>'internal_only')::boolean AND (error_contract->>'sensitive')::boolean AND (error_contract->>'consumes_model_resources')::boolean AND
 handler='internal:agent.missions.work_product.prepare@1.0.0' AND input_schema->'properties'='{}'::jsonb AND input_schema->>'additionalProperties'='false') FROM public.sandy_operation_registry WHERE operation='agent.missions.work_product.prepare';
SELECT pg_temp.mission_assert('worker never invents Auth or owner authority',error_contract->>'principal_kind'='trusted_internal_worker' AND error_contract->'auth_user_id'='null'::jsonb AND (error_contract->>'dedicated_existing_renewal_key')::boolean AND NOT(error_contract->>'public_job_milestone_or_model_selection')::boolean) FROM public.sandy_operation_registry WHERE operation='agent.missions.work_product.prepare';
SELECT pg_temp.mission_assert('RLS and narrow service-only receipt functions',
 (SELECT relrowsecurity FROM pg_class WHERE oid='public.sandy_mission_work_product_audit'::regclass) AND NOT has_table_privilege('authenticated','public.sandy_mission_work_product_audit','SELECT') AND
 NOT has_table_privilege('service_role','public.sandy_mission_work_product_audit','INSERT') AND NOT has_table_privilege('service_role','public.sandy_mission_work_product_audit','UPDATE') AND
 has_function_privilege('service_role','public.sandy_prepare_mission_work_product(uuid,uuid,uuid,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.sandy_prepare_mission_work_product(uuid,uuid,uuid,text)','EXECUTE') AND
 NOT has_function_privilege('anon','public.sandy_finish_mission_work_product(uuid,text,text,text,text,text)','EXECUTE'));
SELECT pg_temp.mission_assert('all original task triggers stay enabled and fixture provenance skips analysis enqueue',
 NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.sandy_tasks'::regclass AND NOT tgisinternal AND tgenabled='D') AND
 NOT EXISTS(SELECT 1 FROM public.sandy_task_analysis_queue WHERE customer_id IN(SELECT customer_id FROM mission_worker_fixtures)));
SELECT pg_temp.mission_reject('wrong source cannot claim',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',run_id,customer_id,mission_id,repeat('f',64)),'mission_work_product_admission_scope_mismatch') FROM mission_worker_fixtures WHERE name='success';
SELECT pg_temp.mission_reject('wrong actual customer cannot claim',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',run_id,gen_random_uuid(),mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4'),'mission_actual_execute_run_scope_required') FROM mission_worker_fixtures WHERE name='success';
UPDATE public.sandy_tasks SET metadata=metadata||jsonb_build_object('mission_run_id',(SELECT plan_id FROM mission_worker_fixtures WHERE name='success'),'depends_on','[]'::jsonb) WHERE id=(SELECT step_id FROM mission_worker_fixtures WHERE name='foreign_plan');
SELECT pg_temp.mission_reject('a foreign plan metadata UUID is not actual tenant scope',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',run_id,customer_id,mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4'),'mission_actual_plan_run_scope_required') FROM mission_worker_fixtures WHERE name='foreign_plan';
UPDATE mission_worker_fixtures f SET audit_id=(public.sandy_prepare_mission_work_product(f.run_id,f.customer_id,f.mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4')->>'id')::uuid WHERE name<>'foreign_plan';
SELECT pg_temp.mission_assert('actual provisional dependency-ready milestone is admitted once',a.state='started' AND a.provisional_plan AND a.milestone_task_id=f.step_id AND a.customer_id=f.customer_id AND a.auth_user_id IS NULL AND j.state='running') FROM mission_worker_fixtures f JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id JOIN public.sandy_mission_runs j ON j.id=f.run_id WHERE f.name='success';
SELECT pg_temp.mission_assert('no eligible step is truthful waiting without a paid dispatch',a.waiting_reason='no_eligible_internal_step' AND a.milestone_task_id IS NULL AND a.provider_response_id IS NULL) FROM mission_worker_fixtures f JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id WHERE f.name='no_eligible';
SELECT pg_temp.mission_assert('uncompleted prerequisite blocks work without a paid dispatch',a.waiting_reason='blocked_by_milestone_dependencies' AND a.milestone_task_id IS NULL AND a.provider_response_id IS NULL) FROM mission_worker_fixtures f JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id WHERE f.name='blocked';
SELECT pg_temp.mission_reject('a started run cannot redispatch',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',run_id,customer_id,mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4'),'mission_work_product_one_use_claim_exists') FROM mission_worker_fixtures WHERE name='unknown';
SELECT pg_temp.mission_reject('receipt scope cannot change at completion',format('UPDATE public.sandy_mission_work_product_audit SET state=''unknown'',error=''mission_work_product_outcome_requires_reconciliation'',finished_at=now(),scope_sha256=%L WHERE id=%L',repeat('a',64),audit_id),'mission_work_product_receipt_scope_immutable') FROM mission_worker_fixtures WHERE name='unknown';
SELECT pg_temp.mission_assert('waiting completion has zero model receipt and no draft',bool_and((public.sandy_finish_mission_work_product(audit_id,'waiting',NULL,NULL,NULL,NULL)->>'ok')::boolean)) FROM mission_worker_fixtures WHERE name IN('no_eligible','blocked');
SELECT pg_temp.mission_assert('unknown result commits durable uncertainty', (public.sandy_finish_mission_work_product(audit_id,'unknown',NULL,NULL,NULL,'mission_work_product_outcome_requires_reconciliation')->>'reconciliation_required')::boolean) FROM mission_worker_fixtures WHERE name='unknown';
SELECT pg_temp.mission_assert('unknown run does not create draft or review work',j.state='failed' AND a.state='unknown' AND a.work_product_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.sandy_mission_work_products WHERE run_id=f.run_id)) FROM mission_worker_fixtures f JOIN public.sandy_mission_runs j ON j.id=f.run_id JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id WHERE f.name='unknown';
UPDATE public.sandy_mission_runs SET state='queued' WHERE id=(SELECT run_id FROM mission_worker_fixtures WHERE name='unknown');
SELECT pg_temp.mission_reject('resetting job status cannot repeat unknown paid work',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',run_id,customer_id,mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4'),'mission_work_product_one_use_claim_exists') FROM mission_worker_fixtures WHERE name='unknown';
UPDATE public.sandy_mission_runs SET state='failed' WHERE id=(SELECT run_id FROM mission_worker_fixtures WHERE name='unknown');
CREATE TEMP TABLE mission_cross_run(id uuid);
WITH added AS(INSERT INTO public.sandy_mission_runs(mission_task_id,customer_id,stage,state,run_key) SELECT mission_id,customer_id,'execute','queued','rollback-cross-run:'||gen_random_uuid() FROM mission_worker_fixtures WHERE name='unknown' RETURNING id) INSERT INTO mission_cross_run SELECT id FROM added;
SELECT pg_temp.mission_reject('another run ID cannot repeat an unknown milestone model outcome',format('SELECT public.sandy_prepare_mission_work_product(%L,%L,%L,%L)',c.id,f.customer_id,f.mission_id,'6f6b7ce3d1bca03d9637c46a3535c4f288efef4c3a5532cc8a6ef5a6de3b0dc4'),'mission_milestone_outcome_requires_reconciliation') FROM mission_cross_run c CROSS JOIN mission_worker_fixtures f WHERE f.name='unknown';
UPDATE public.sandy_tasks SET metadata=metadata||'{"plan_summary":"The customer changed this context"}'::jsonb WHERE id=(SELECT mission_id FROM mission_worker_fixtures WHERE name='changed');
SELECT pg_temp.mission_reject('changed customer context cannot be overwritten by stale draft completion',format('SELECT public.sandy_finish_mission_work_product(%L,''succeeded'',''resp_rollback'',%L,%L,NULL)',audit_id,repeat('a',64),jsonb_build_object('title','Rollback editable draft','content',repeat('Editable draft pending client review. ',6),'content_type','checklist')::text),'mission_work_product_context_changed_reconcile') FROM mission_worker_fixtures WHERE name='changed';
SELECT pg_temp.mission_assert('context rejection leaves all draft/review writes atomic',NOT EXISTS(SELECT 1 FROM public.sandy_mission_work_products WHERE run_id=f.run_id) AND NOT EXISTS(SELECT 1 FROM public.sandy_tasks WHERE parent_task_id=f.mission_id AND metadata->>'stage'='deliverable_review')) FROM mission_worker_fixtures f WHERE name='changed';
UPDATE public.sandy_tasks SET status='cancelled' WHERE id=(SELECT mission_id FROM mission_worker_fixtures WHERE name='cancelled');
SELECT pg_temp.mission_reject('cancelled mission is not reopened by model output',format('SELECT public.sandy_finish_mission_work_product(%L,''succeeded'',''resp_rollback'',%L,%L,NULL)',audit_id,repeat('a',64),jsonb_build_object('title','Rollback editable draft','content',repeat('Editable draft pending client review. ',6),'content_type','checklist')::text),'mission_unavailable') FROM mission_worker_fixtures WHERE name='cancelled';
SELECT pg_temp.mission_reject('bare assertion without model response receipt cannot record success',format('SELECT public.sandy_finish_mission_work_product(%L,''succeeded'',NULL,NULL,%L,NULL)',audit_id,jsonb_build_object('title','Rollback editable draft','content',repeat('Editable draft pending client review. ',6),'content_type','checklist')::text),'mission_work_product_actual_model_receipt_required') FROM mission_worker_fixtures WHERE name='success';
SELECT pg_temp.mission_assert('atomic success stores actual pending-review draft and client review task', (public.sandy_finish_mission_work_product(audit_id,'succeeded','resp_rollback_component_not_provider_test',repeat('a',64),jsonb_build_object('title','Rollback editable draft','content',repeat('Editable draft pending client review. ',6),'content_type','checklist')::text,NULL)->>'ok')::boolean) FROM mission_worker_fixtures WHERE name='success';
SELECT pg_temp.mission_assert('stored draft is scoped and not approved or researched',p.customer_id=f.customer_id AND p.mission_task_id=f.mission_id AND p.milestone_task_id=f.step_id AND p.state='pending_review' AND p.sources='[]'::jsonb AND a.state='succeeded' AND a.review_task_id IS NOT NULL) FROM mission_worker_fixtures f JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id JOIN public.sandy_mission_work_products p ON p.id=a.work_product_id WHERE f.name='success';
SELECT pg_temp.mission_assert('provisional plan remains pending plan review with exact client-owned review work',m.metadata->>'execution_state'='awaiting_client_plan_review' AND t.status='waiting' AND t.metadata->>'execution_state'='draft_pending_review' AND r.parent_task_id=m.id AND r.customer_id=f.customer_id AND r.metadata->>'assigned_to'='client' AND r.metadata->>'stage'='deliverable_review' AND j.state='completed' AND j.result->>'external_actions_performed'='0') FROM mission_worker_fixtures f JOIN public.sandy_mission_work_product_audit a ON a.id=f.audit_id JOIN public.sandy_tasks m ON m.id=f.mission_id JOIN public.sandy_tasks t ON t.id=f.step_id JOIN public.sandy_tasks r ON r.id=a.review_task_id JOIN public.sandy_mission_runs j ON j.id=f.run_id WHERE f.name='success';
SELECT pg_temp.mission_assert('actual mission event keeps zero external actions',EXISTS(SELECT 1 FROM public.sandy_task_events e WHERE e.task_id=f.mission_id AND e.customer_id=f.customer_id AND e.event_type='mission_internal_draft_prepared' AND e.snapshot->>'run_id'=f.run_id::text AND e.snapshot->>'external_actions_performed'='0')) FROM mission_worker_fixtures f WHERE f.name='success';
SELECT pg_temp.mission_reject('successful final RPC cannot duplicate a work product or review',format('SELECT public.sandy_finish_mission_work_product(%L,''succeeded'',''resp_repeat'',%L,%L,NULL)',audit_id,repeat('a',64),jsonb_build_object('title','Rollback editable draft','content',repeat('Editable draft pending client review. ',6),'content_type','checklist')::text),'mission_work_product_finish_claim_required') FROM mission_worker_fixtures WHERE name='success';
SELECT pg_temp.mission_assert('single product and review remain after refused repeat', (SELECT count(*) FROM public.sandy_mission_work_products WHERE run_id=f.run_id)=1 AND (SELECT count(*) FROM public.sandy_tasks WHERE parent_task_id=f.mission_id AND metadata->>'stage'='deliverable_review')=1) FROM mission_worker_fixtures f WHERE f.name='success';
SELECT pg_temp.mission_assert('task analysis HTTP remains an uncommitted MVCC outbox insert, not synchronous HTTP',
 (SELECT l.lanname='plpgsql' AND position('insert into net.http_request_queue' IN p.prosrc)>0 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='net.http_post(text,jsonb,jsonb,jsonb,integer)'::regprocedure));
SELECT jsonb_build_object('status','pass','component_checks',count(*),'real_provider_calls',0,'real_model_calls',0,'real_customer_execution_tested',false,'all_production_triggers_enabled',NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.sandy_tasks'::regclass AND NOT tgisinternal AND tgenabled='D'),
 'fixture_customer_ids',(SELECT jsonb_agg(customer_id) FROM mission_worker_fixtures),'uncommitted_http_outbox_ids',(SELECT coalesce(jsonb_agg(id),'[]'::jsonb) FROM net.http_request_queue WHERE pg_xact_status(xmin::text::xid8)='in progress'),'all_changes_rolled_back',true) AS mission_work_product_evidence FROM mission_worker_checks;
ROLLBACK;
